"""
Module 5 - JSON Validation

Configuration

Contains all rules used to validate the OCR JSON
generated by Module 4.

IMPORTANT:
This module does not modify OCR data.
It only defines validation behavior.
"""


class JSONValidationConfig:

    # =========================================================
    # INPUT
    # =========================================================

    # JSON file generated by Module 4
    INPUT_FOLDER = "output/module_4"

    INPUT_FILENAME = "ocr_result.json"

    # =========================================================
    # REQUIRED DOCUMENT FIELDS
    # =========================================================

    REQUIRE_DOCUMENT = True

    REQUIRE_TOTAL_PAGES = True

    REQUIRE_COVER_PAGE = True

    REQUIRE_ANSWER_PAGES = True

    REQUIRE_PAGES = True

    # =========================================================
    # STUDENT INFORMATION
    # =========================================================

    REQUIRE_STUDENT_OBJECT = True

    # Individual fields are allowed to be null because
    # the information may not be visible on the cover page.

    STUDENT_FIELDS = [

        "student_name",

        "register_number",

        "roll_number",

        "subject",

        "course",

        "semester",

        "examination",

        "date"

    ]

    # =========================================================
    # ANSWER FIELDS
    # =========================================================

    REQUIRE_ANSWER_NUMBER = True

    REQUIRE_ANSWER_TEXT = True

    REQUIRE_CONTINUATION_FLAG = True

    REQUIRE_SOURCE_PAGE = True

    # =========================================================
    # ANSWER CONTENT
    # =========================================================

    # Empty answer text is considered invalid.
    ALLOW_EMPTY_ANSWER_TEXT = False

    # Whitespace-only text is also considered empty.
    ALLOW_WHITESPACE_ONLY_TEXT = False

    # =========================================================
    # PAGE INFORMATION
    # =========================================================

    REQUIRE_PAGE_NUMBER = True

    REQUIRE_PAGE_TYPE = True

    ALLOWED_PAGE_TYPES = [

        "COVER",

        "ANSWER"

    ]

    # =========================================================
    # DATA TYPES
    # =========================================================

    ALLOWED_ANSWER_NUMBER_TYPES = (

        int,

        str,

        type(None)

    )

    ALLOWED_PAGE_NUMBER_TYPES = (

        int,

    )

    ALLOWED_SOURCE_PAGE_TYPES = (

        int,

    )

    # =========================================================
    # CONTINUATION
    # =========================================================

    REQUIRE_BOOLEAN_CONTINUATION = True

    # =========================================================
    # CONSISTENCY CHECKS
    # =========================================================

    CHECK_PAGE_NUMBER_RANGE = True

    CHECK_SOURCE_PAGE_RANGE = True

    CHECK_ANSWER_PAGE_REFERENCE = True

    CHECK_DUPLICATE_PAGE_NUMBERS = True

    # =========================================================
    # VALIDATION BEHAVIOR
    # =========================================================

    # IMPORTANT:
    #
    # Validation must NEVER modify the OCR output.

    MODIFY_OCR_DATA = False

    AUTO_CORRECT = False

    ADD_MISSING_TEXT = False

    REMOVE_TEXT = False

    # =========================================================
    # OUTPUT
    # =========================================================

    OUTPUT_FOLDER = "output/module_5"

    VALIDATED_FILENAME = "validated_ocr.json"

    REPORT_FILENAME = "validation_report.json"

    SAVE_VALIDATED_COPY = True

    SAVE_REPORT = True

    # =========================================================
    # VALIDATION STATUS
    # =========================================================

    STATUS_VALID = "VALID"

    STATUS_INVALID = "INVALID"

    STATUS_WARNING = "WARNING"